namespace {
QString debugText(QJsonValue v){if(v.isString())return v.toString();if(v.isBool())return v.toBool()?QObject::tr("참"):QObject::tr("거짓");if(v.isDouble())return QString::number(v.toDouble(),'g',15);if(v.isNull()||v.isUndefined())return "—";return QString::fromUtf8(v.isObject()?QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact):QJsonDocument(v.toArray()).toJson(QJsonDocument::Compact));}
}

void StudioWindow::showRuleDebugger(){
  if(ruleDebugDock){ruleDebugDock->show();ruleDebugDock->raise();return;}
  ruleDebugDock=new QDockWidget(tr("규칙 디버거 · 영향 분석"),this);ruleDebugDock->setObjectName("ruleDebugDock");ruleDebugDock->setWidget(makeRuleDebuggerPanel());
  addDockWidget(Qt::RightDockWidgetArea,ruleDebugDock);ruleDebugDock->setFloating(true);ruleDebugDock->resize(1100,950);ruleDebugDock->show();
}
