  auto target=new QComboBox;target->setObjectName("debugCommandTarget");auto item=new QComboBox;item->setObjectName("debugCommandItem");auto quantity=new QSpinBox;quantity->setObjectName("debugQuantity");quantity->setRange(1,999);form->addRow(tr("대상"),target);form->addRow(tr("상품 / 선택지"),item);form->addRow(tr("수량"),quantity);auto execute=new QPushButton(tr("한 단계 실행"));execute->setObjectName("debugExecute");form->addRow(execute);box->addWidget(commands);
  auto tabs=new QTabWidget;box->addWidget(tabs,1);auto makeTree=[&](QString name,QString caption,QStringList columns){auto t=new QTreeWidget;t->setObjectName(name);t->setHeaderLabels(columns);t->setAlternatingRowColors(true);tabs->addTab(t,caption);return t;};
