  auto fillSubjects=[this,type,subject,actor]{const auto priorActor=actor->currentData();actor->clear();actor->addItem(tr("공용 / 실행자 없음"),QString());for(const auto &v:projectData().value("roster").toObject().value("members").toArray()){const auto id=v.toObject().value("characterId").toString();actor->addItem(id,id);}actor->setCurrentIndex(qMax(0,actor->findData(priorActor)));const auto prior=subject->currentData();subject->clear();if(type->currentData()=="action")for(auto v:projectData().value("gameplay").toObject().value("actions").toArray()){auto a=v.toObject();subject->addItem(a.value("name").toString(),a.value("id").toString());}else for(auto v:view.value("documents").toArray()){auto d=v.toObject();if(d.value("kind")=="event"){auto e=d.value("data").toObject();subject->addItem(e.value("label").toString(),e.value("id").toString());}}int i=subject->findData(prior);if(i>=0)subject->setCurrentIndex(i);};
