    trace->clear();QJsonArray rows=d.value("trace").toArray();const auto inspection=d.value("inspection").toObject();if(rows.empty())rows=inspection.value("trace").toArray();for(auto v:rows){const auto e=v.toObject();auto n=new QTreeWidgetItem(trace);n->setText(0,e.value("kind").toString()+" "+e.value("actionId").toString(e.value("ruleId").toString()));n->setText(1,e.value("status").toString(debugText(e.contains("after")?e.value("after"):e.value("value"))));n->setText(2,e.value("path").toString()+" "+e.value("reason").toString());n->setToolTip(0,debugText(e));}
    diff->clear();auto changes=d.value("diff").toArray();if(changes.empty()&&!inspection.empty())changes=inspection.value("preview").toObject().value("diff").toArray();for(auto v:changes){auto c=v.toObject();new QTreeWidgetItem(diff,{c.value("path").toString(),debugText(c.value("before")),debugText(c.value("after"))});}
