  connect(this,&StudioWindow::updated,panel,[this,fillSubjects,fillCommands,revision=std::make_shared<int>(view.value("revision").toInt())]{if(*revision!=view.value("revision").toInt()){*revision=view.value("revision").toInt();fillSubjects();fillCommands();}});
